self.onInit = function() {
    var courses = [];
    var initialLoad = true;

    self.onDataUpdated = function() {
        if (self.ctx.data.length > 0) {
            var attrData = self.ctx.data.find(d => d.dataKey.name === 'available_courses');
            if (attrData && attrData.data.length > 0) {
                var val = attrData.data[0][1];
                var newCourses = val ? val.split(',').map(c => c.trim()).filter(c => c && c !== 'undefined') : [];
                // Only overwrite if it's the first load, to prevent WebSocket race conditions overriding our local state
                if (initialLoad) {
                    courses = newCourses;
                    initialLoad = false;
                    renderList();
                }
            }
        }
    };

    function renderList() {
        var list = $('.course-list', self.ctx.$container);
        if (list.length === 0) return;
        list.empty();

        courses.forEach(function(course, index) {
            list.append(`<li><span>${course}</span> <button data-idx="${index}" class="del-btn">Delete</button></li>`);
        });

        $('.del-btn', self.ctx.$container).on('click', function() {
            courses.splice($(this).data('idx'), 1);
            renderList();
            saveToServer();
        });
    }

    // Wait slightly to ensure HTML is rendered
    setTimeout(function() {
        $('.add-course-btn', self.ctx.$container).on('click', function() {
            var input = $('.new-course-input', self.ctx.$container);
            var val = input.val().trim();
            if (val) {
                if(!courses.includes(val)) {
                    courses.push(val);
                    input.val('');
                    renderList();
                    saveToServer();
                } else {
                    alert("Course already exists!");
                }
            }
        });
    }, 200);

    function saveToServer() {
        if (!self.ctx.datasources || self.ctx.datasources.length === 0) return;
        var ds = self.ctx.datasources[0];
        var eId = ds.entityId || (ds.entity ? ds.entity.id : null);
        var eType = ds.entityType || (ds.entity ? ds.entity.entityType : null);
        if (!eId || !eType) return;

        var newString = courses.join(',');
        var token = window.localStorage.getItem('jwt_token');

        if (!token) {
            alert("Error: Cannot find authentication token.");
            return;
        }

        var url = '/api/plugins/telemetry/' + eType + '/' + eId + '/attributes/SHARED_SCOPE';
        var payload = { "available_courses": newString };

        fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Authorization': 'Bearer ' + token
            },
            body: JSON.stringify(payload)
        }).then(function(response) {
            if (!response.ok) {
                alert("Save failed: " + response.statusText);
            }
        }).catch(function(err) {
            alert("Save error: " + err.message);
        });
    }
};
